import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == pytest.approx(1 / 3)
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_once():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 5) == 3
    assert flags_in_window([1, 2], 0) == 0


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log(
        ["  # comment", "", "  ", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,not-a-day,1", "x,1,maybe"])
def test_parse_transcript_log_reports_input_line_number(bad_line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# skipped", bad_line])


def test_dedupe_transcripts_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "a", "day": 4, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_empty_reverse_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 3, "flagged": True},
        {"id": "e", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 3) == [0, 2]
    assert daily_flag_counts(events, 4, 3) == []


def test_monitor_summary_rounds_rate_and_counts_nonempty_groups():
    groups = {
        "a": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 2, "flagged": False},
        ],
        "empty": [],
        "b": [{"id": "c", "day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 5) == {
        "rate": 0.0,
        "recent": 0,
        "groups": 0,
    }


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": True}],
        "a": [{"flagged": True}],
        "lower": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "b"]
    assert top_flagged_groups(groups, 10) == ["a", "b", "z", "lower"]


def test_flag_rate_by_group_empty_values_and_sorted_keys():
    result = flag_rate_by_group({"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]})
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_counts_only_positive_values():
    assert longest_flag_streak([0, 1, 2, 0, 3]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([-1, 0]) == 0

